package limiter

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time so tests can control it.
type Clock interface {
	Now() time.Time
}

// realClock uses the standard library.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu     sync.Mutex
	tokens float64
	last   time.Time

	Burst int           // maximum tokens the bucket can hold
	Rate  time.Duration // interval between token refills (tokens per Rate)
	clock Clock
}

// New creates a Limiter with a full bucket. burst must be > 0 and
// rate must be > 0. Uses the real clock.
func New(burst int, rate time.Duration) (*Limiter, error) {
	return NewWithClock(burst, rate, realClock{})
}

// NewWithClock is like New but accepts an injectable clock (useful for tests).
func NewWithClock(burst int, rate time.Duration, clock Clock) (*Limiter, error) {
	if burst <= 0 {
		return nil, errors.New("limiter: burst must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("limiter: rate must be positive")
	}
	if clock == nil {
		return nil, errors.New("limiter: nil clock")
	}
	return &Limiter{
		tokens: float64(burst),
		last:   clock.Now(),
		Burst:  burst,
		Rate:   rate,
		clock:  clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// Tokens accrue lazily based on elapsed time since the last call.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last)
	if elapsed > 0 {
		l.tokens += elapsed.Seconds() / l.Rate.Seconds()
		if l.tokens > float64(l.Burst) {
			l.tokens = float64(l.Burst)
		}
	}
	l.last = now

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	elapsed := now.Sub(l.last)
	t := l.tokens
	if elapsed > 0 {
		t += elapsed.Seconds() / l.Rate.Seconds()
		if t > float64(l.Burst) {
			t = float64(l.Burst)
		}
	}
	return t
}
